// Browser port of phishdetect (features.py + heuristics.py + detector.py).
// The decision tree and every rule list come from model.json, generated by
// `python -m phishdetect export-web`. Only the logic lives here.
// tests/test_web_parity.py checks this file against the Python engine.

let M = null;
let S = null; // lists turned into Sets

export function init(model) {
  M = model;
  const L = model.lists;
  S = {
    knownTlds: new Set(L.known_tlds),
    shorteners: new Set(L.url_shorteners),
    suspiciousTlds: new Set(L.suspicious_tlds),
    freeHosting: L.free_hosting,
    trusted: new Set(L.trusted_domains),
    secondLevel: new Set(L.second_level),
    redirectKeys: new Set(L.redirect_keys),
    official: new Set(Object.values(L.brands).flat()),
  };
}

// ---------------------------------------------------------------- features

const SCHEME = /^[a-z][a-z0-9+.\-]*:\/\//i;
const IPV4 = /^\d{1,3}(\.\d{1,3}){3}$/;
const HEX_IP = /^0x[0-9a-f]{8}$/i;
const DEC_IP = /^\d{8,10}$/;
const EMAIL = /[\w.+-]+@[\w-]+\.[\w.-]+/;

export function unquote(text) {
  // Same as Python's urllib.parse.unquote: %XX runs decoded as UTF-8, bad bytes -> U+FFFD.
  return text.replace(/(%[0-9a-f]{2})+/gi, (run) => {
    const bytes = new Uint8Array(run.length / 3);
    for (let i = 0; i < bytes.length; i++) bytes[i] = parseInt(run.substr(i * 3 + 1, 2), 16);
    return new TextDecoder("utf-8").decode(bytes);
  });
}

export function refang(url) {
  let out = url.trim().replace(/^[<>"']+|[<>"']+$/g, "");
  out = out.replace(/^hxxp/i, "http").replace(/^fxp/i, "ftp");
  out = out.replace(/\[\.\]|\(\.\)|\{\.\}|\[dot\]|\(dot\)/gi, ".");
  out = out.replace(/\[:\]|\[:\/\/\]/g, (m) => m.slice(1, -1));
  out = out.replace(/\[at\]|\(at\)/gi, "@");
  return out;
}

export function defang(url) {
  return url.replace(/^http/i, "hxxp").split(".").join("[.]");
}

const count = (text, ch) => text.split(ch).length - 1;

export function splitUrl(url) {
  let text = refang(url).replace(SCHEME, "");
  if (text.endsWith("/") && count(text, "/") === 1) text = text.slice(0, -1);

  const m = text.match(/^([^/?#]*)(\/[^?#]*)?(\?[^#]*)?(#.*)?$/) || [text, text];
  const authority = m[1] ?? "";
  const path = m[2] ?? null;
  const query = m[3] ?? null;

  let host = authority.slice(authority.lastIndexOf("@") + 1);
  let port = null;
  if (host.startsWith("[")) {
    const end = host.indexOf("]");
    port = host.slice(end + 1, end + 2) === ":" ? host.slice(end + 2) : null;
    host = host.slice(1, end);
  } else if (host.includes(":")) {
    const i = host.indexOf(":");
    port = host.slice(i + 1);
    host = host.slice(0, i);
  }
  return {
    url: text,
    authority,
    domain: host.toLowerCase(),
    port,
    directory: path,
    file: path ? path.slice(path.lastIndexOf("/") + 1) : null,
    params: query ? query.slice(1) : null,
  };
}

export function isIpHost(host) {
  return IPV4.test(host) || HEX_IP.test(host) || DEC_IP.test(host) || host.includes(":");
}

function tldTokens(text) {
  const out = [];
  for (const m of text.toLowerCase().matchAll(/\.([a-z]{2,})(?=$|[./?:#&=_\-])/g)) {
    if (S.knownTlds.has(m[1])) out.push(m[1]);
  }
  return out;
}

function countChars(text, part, f) {
  for (const [name, ch] of Object.entries(M.lists.special_chars)) {
    f[`qty_${name}_${part}`] = text === null ? -1 : count(text, ch);
  }
}

export function extractFeatures(url) {
  const p = splitUrl(url);
  const text = p.url, domain = p.domain;
  const f = {};

  countChars(text, "url", f);
  f.qty_tld_url = tldTokens(text).length;
  f.length_url = text.length;

  countChars(domain, "domain", f);
  f.qty_vowels_domain = [..."aeiou"].reduce((n, v) => n + count(domain, v), 0);
  f.domain_length = domain.length;
  f.domain_in_ip = isIpHost(domain) ? 1 : 0;
  f.server_client_domain = domain.includes("server") || domain.includes("client") ? 1 : 0;

  countChars(p.directory, "directory", f);
  f.directory_length = p.directory === null ? -1 : p.directory.length;

  countChars(p.file, "file", f);
  f.file_length = p.file === null ? -1 : p.file.length;

  const params = p.params;
  countChars(params, "params", f);
  if (params === null) {
    f.params_length = f.tld_present_params = f.qty_params = -1;
  } else {
    f.params_length = params.length;
    f.tld_present_params = tldTokens(unquote(params)).length ? 1 : 0;
    f.qty_params = params.split("&").filter(Boolean).length;
  }

  f.email_in_url = EMAIL.test(unquote(text)) ? 1 : 0;
  f.url_shortened = S.shorteners.has(domain.startsWith("www.") ? domain.slice(4) : domain) ? 1 : 0;
  return f;
}

// ---------------------------------------------------------------- rules

export function registeredDomain(host) {
  const labels = host.replace(/^\.+|\.+$/g, "").split(".");
  const n = labels.length;
  if (n >= 3 && labels[n - 1].length === 2 && S.secondLevel.has(labels[n - 2])) return labels.slice(-3).join(".");
  return labels.slice(-2).join(".");
}

export function levenshtein(a, b) {
  a = [...a]; b = [...b];
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] !== b[j - 1] ? 1 : 0)));
    }
    prev = cur;
  }
  return prev[prev.length - 1];
}

function entropy(text) {
  if (!text) return 0;
  const counts = {};
  for (const c of text) counts[c] = (counts[c] || 0) + 1;
  return -Object.values(counts).reduce((s, n) => s + (n / text.length) * Math.log2(n / text.length), 0);
}

function fold(label) {
  for (const [src, dst] of M.lists.homoglyphs) label = label.split(src).join(dst);
  return label;
}

function skeleton(text) {
  return fold([...text].map((c) => M.lists.confusables[c] ?? c).join(""));
}

// RFC 3492 decoder, enough for "xn--" labels.
function punycodeDecode(input) {
  const base = 36, tMin = 1, tMax = 26, skew = 38, damp = 700;
  const adapt = (delta, numPoints, first) => {
    delta = first ? Math.floor(delta / damp) : delta >> 1;
    delta += Math.floor(delta / numPoints);
    let k = 0;
    while (delta > ((base - tMin) * tMax) >> 1) { delta = Math.floor(delta / (base - tMin)); k += base; }
    return k + Math.floor(((base - tMin + 1) * delta) / (delta + skew));
  };
  const digit = (c) => {
    const cp = c.charCodeAt(0);
    if (cp >= 48 && cp <= 57) return cp - 22;
    if (cp >= 65 && cp <= 90) return cp - 65;
    if (cp >= 97 && cp <= 122) return cp - 97;
    throw new Error("bad punycode");
  };
  const d = input.lastIndexOf("-");
  const out = d > 0 ? [...input.slice(0, d)].map((c) => c.codePointAt(0)) : [];
  let n = 128, i = 0, bias = 72;
  for (let pos = d > 0 ? d + 1 : 0; pos < input.length;) {
    const oldi = i;
    for (let w = 1, k = base; ; k += base) {
      if (pos >= input.length) throw new Error("bad punycode");
      const dg = digit(input[pos++]);
      i += dg * w;
      const t = k <= bias ? tMin : k >= bias + tMax ? tMax : k - bias;
      if (dg < t) break;
      w *= base - t;
    }
    bias = adapt(i - oldi, out.length + 1, oldi === 0);
    n += Math.floor(i / (out.length + 1));
    i %= out.length + 1;
    out.splice(i++, 0, n);
  }
  return String.fromCodePoint(...out);
}

export function unicodeHost(host) {
  return host.split(".").map((label) => {
    if (!label.startsWith("xn--")) return label;
    try { return punycodeDecode(label.slice(4)); } catch { return label; }
  }).join(".");
}

const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\\-]/g, "\\$&");

function onFreeHosting(host) {
  return M.lists.free_hosting.find((fh) => host === fh || host.endsWith("." + fh)) || null;
}

function containsBrand(label, brand) {
  if (brand.length >= 6) return label.includes(brand);
  return new RegExp(`(^|[\\-\\d])${brand}([\\-\\d]|$)`).test(label);
}

const hasBrand = (label, brand) => containsBrand(label, brand) || containsBrand(fold(label), brand);

function typosquatTarget(sld, reg) {
  const folded = fold(sld);
  const brands = Object.values(M.lists.brands);
  if (brands.some((ds) => ds.includes(reg))) return null;
  for (const ds of brands) {
    const ordered = [...ds].sort((a, b) => (a.endsWith(".com") === b.endsWith(".com") ? (a < b ? -1 : a > b ? 1 : 0) : a.endsWith(".com") ? -1 : 1));
    for (const official of ordered) {
      const target = official.split(".")[0];
      if (sld === target || target.length < 5) continue;
      const dist = levenshtein(folded, target);
      if (folded === target || dist === 1 || (dist === 2 && target.length >= 9)) return official;
    }
  }
  return null;
}

function parseQs(params) {
  // urllib.parse.parse_qs(keep_blank_values=True), insertion ordered.
  const out = new Map();
  const dec = (s) => unquote(s.replace(/\+/g, " "));
  for (const pair of params.split("&")) {
    if (!pair) continue;
    const i = pair.indexOf("=");
    const k = dec(i < 0 ? pair : pair.slice(0, i));
    const v = dec(i < 0 ? "" : pair.slice(i + 1));
    if (!out.has(k)) out.set(k, []);
    out.get(k).push(v);
  }
  return out;
}

export function analyze(url) {
  const p = splitUrl(url);
  const host = p.domain, raw = p.url;
  const findings = [];
  const add = (rule, severity, detail) => findings.push({ rule, severity, detail });
  const L = M.lists;

  const sm = url.trim().match(/^\s*([a-z][a-z0-9+.\-]*):(?!\d)/i);
  const scheme = sm ? sm[1].toLowerCase() : null;
  if (["data", "javascript", "vbscript", "file"].includes(scheme)) {
    add("dangerous_scheme", "critical", `'${scheme}:' URI can run or load content without a website`);
    return findings;
  }
  if (scheme === "http") add("cleartext_http", "low", "no TLS: credentials would travel in clear text");

  if (!host || (!host.includes(".") && !isIpHost(host))) {
    add("malformed_host", "medium", `host '${host}' is not a valid public hostname`);
    return findings;
  }

  const ip = isIpHost(host);
  const reg = ip ? host : registeredDomain(host);
  const labels = host.split(".");
  const sld = reg.split(".")[0];
  const tld = labels[labels.length - 1];
  const pathAndQuery = unquote(((p.directory ?? "") + "?" + (p.params ?? "")).toLowerCase());

  if (ip) add("ip_host", "high", `host is a raw IP address (${host}) instead of a domain name`);

  if (p.authority.includes("@")) {
    add("userinfo_trick", "critical",
      `'${p.authority.split("@")[0]}@' before the host: the browser actually connects to ${host}`);
  }

  if (p.port && p.port !== "80" && p.port !== "443") add("non_standard_port", "medium", `explicit port :${p.port}`);

  if (host.includes("xn--") || [...host].some((c) => c.codePointAt(0) > 127)) {
    const decoded = unicodeHost(host);
    const lookalike = skeleton(registeredDomain(decoded).split(".")[0]);
    let hit = null;
    for (const ds of Object.values(L.brands)) {
      hit = ds.find((d) => d.split(".")[0] === lookalike) || null;
      if (hit) break;
    }
    if (hit) add("homoglyph", "critical", `'${decoded}' renders like ${hit} but uses look-alike Unicode letters`);
    else add("idn_host", "medium", `internationalized hostname, displays as '${decoded}'`);
  }

  if (S.shorteners.has(reg.startsWith("www.") ? reg.slice(4) : reg) || S.shorteners.has(host)) {
    add("url_shortener", "medium", `${host} is a URL shortener: real destination is hidden`);
  }

  const fh = onFreeHosting(host);
  if (fh) add("free_hosting", "medium", `hosted on ${fh} (free / user-generated hosting)`);

  if (S.suspiciousTlds.has(tld)) add("suspicious_tld", "medium", `.${tld} is heavily abused in phishing campaigns`);

  if (!ip) {
    const subdomains = labels.slice(0, labels.length - reg.split(".").length);
    if (subdomains.length >= 3) {
      add("deep_subdomains", "medium", `${subdomains.length} subdomain levels (${subdomains.join(".")})`);
    }

    const known = (S.official.has(reg) || S.trusted.has(reg)) && !fh;
    if (!known) {
      for (const brand of Object.keys(L.brands)) {
        if (subdomains.some((s) => hasBrand(s, brand))) {
          add("brand_in_subdomain", "high", `'${brand}' appears in the subdomain but the real domain is ${reg}`);
          break;
        }
        if (hasBrand(sld, brand)) {
          add("brand_in_domain", "high", `'${brand}' embedded in ${reg}, which is not an official ${brand} domain`);
          break;
        }
        if (new RegExp(`(^|[/._\\-])${brand}([/._\\-]|$)`).test(pathAndQuery)) {
          add("brand_in_path", "medium", `'${brand}' referenced in the path of ${reg}`);
          break;
        }
      }
    }

    const official = typosquatTarget(sld, reg);
    if (official) {
      const target = official.split(".")[0];
      const sev = fold(sld) === target ? "critical" : "high";
      add("typosquat", sev, `${reg} imitates ${official} (edit distance ${levenshtein(sld, target)})`);
      for (let i = findings.length - 1; i >= 0; i--) if (findings[i].rule === "brand_in_domain") findings.splice(i, 1);
    }

    const vowels = [..."aeiou"].reduce((n, v) => n + count(sld, v), 0) / Math.max(sld.length, 1);
    if (sld.length >= 12 && entropy(sld) > 3.5 && vowels < 0.3) {
      add("high_entropy_domain", "medium", `'${sld}' looks randomly generated (entropy ${entropy(sld).toFixed(2)})`);
    }
    if (count(sld, "-") >= 2 && !sld.startsWith("xn--")) add("hyphenated_domain", "low", `${count(sld, "-")} hyphens in '${sld}'`);
    if (!sld.startsWith("xn--") && /[a-z]/.test(sld) && (sld.match(/\d/g) || []).length >= 4) {
      add("digits_in_domain", "low", `many digits mixed into '${sld}'`);
    }
  }

  const haystack = host + "/" + pathAndQuery;
  const hits = L.sensitive_words.filter((w) => new RegExp(`(?<![a-z])${escapeRe(w)}`).test(haystack)).sort();
  if (hits.length) add("credential_keywords", hits.length >= 2 ? "medium" : "low", "lure keywords: " + hits.join(", "));

  const file = p.file ?? "";
  if (/\.(pdf|docx?|xlsx?|jpg|png|txt)\.(exe|scr|js|vbs|hta|html?|zip)$/i.test(file)) {
    add("double_extension", "critical", `double extension in '${file}'`);
  } else if (/\.(exe|scr|js|vbs|hta|jar|msi|bat|cmd|ps1|iso|img|lnk|apk)$/i.test(file)) {
    add("executable_download", "high", `link points to an executable/script: '${file}'`);
  }

  if (p.params) {
    for (const [key, values] of parseQs(p.params)) {
      if (S.redirectKeys.has(key.toLowerCase()) && values.some((v) => /^(https?:)?\/\//i.test(v))) {
        add("open_redirect", "high", `parameter '${key}' forwards to another URL`);
        break;
      }
    }
    if (EMAIL.test(unquote(p.params))) {
      add("email_in_params", "medium", "victim e-mail address pre-filled in the URL (targeted lure)");
    }
  }

  if (raw.length > 100) add("long_url", "low", `URL is ${raw.length} characters long`);
  if ((p.directory ?? "").includes("//")) add("embedded_url", "medium", "'//' inside the path: URL nested in another URL");
  if (host.includes("%") || /(%[0-9a-f]{2}){5,}/i.test(raw)) add("heavy_encoding", "low", "percent-encoding used to hide characters");

  return findings;
}

export function isTrusted(url, extra = new Set()) {
  const host = splitUrl(url).domain;
  if (!host || isIpHost(host) || onFreeHosting(host)) return false;
  const reg = registeredDomain(host);
  return S.trusted.has(reg) || S.official.has(reg) || extra.has(reg) || extra.has(host);
}

const weight = (f) => M.scoring.severity_weight[f.severity];

export function heuristicScore(findings) {
  return 1 - findings.reduce((clean, f) => clean * (1 - weight(f)), 1);
}

// ---------------------------------------------------------------- tree + verdict

function pct0(x) {
  // Python's "{:.0%}" (round half to even).
  const v = x * 100, fl = Math.floor(v);
  const r = v - fl === 0.5 ? (fl % 2 === 0 ? fl : fl + 1) : Math.round(v);
  return `${r}%`;
}

function walk(features) {
  const t = M.tree;
  const path = [];
  let node = 0;
  while (t.left[node] !== -1) {
    const col = M.columns[t.feature[node]];
    const val = features[col];
    const thr = t.threshold[node];
    const goLeft = Math.fround(val) <= thr; // sklearn compares float32(X) to the threshold
    path.push(`${col} = ${val} ${goLeft ? "<=" : ">"} ${thr.toFixed(2)}`);
    node = goLeft ? t.left[node] : t.right[node];
  }
  path.push(`leaf #${node}: ${pct0(t.p[node])} of training URLs here were phishing`);
  return { p: t.p[node], path };
}

export function scan(input, allowlist = new Set()) {
  const url = refang(input);
  const feats = extractFeatures(url);
  const { p: pTree, path } = walk(feats);
  const findings = analyze(url);
  const h = heuristicScore(findings);
  let risk = 1 - (1 - pTree) * (1 - h);

  const trusted = isTrusted(url, allowlist);
  const strong = findings.some((f) => f.severity === "high" || f.severity === "critical");
  if (trusted && !strong) risk = Math.min(risk, h);

  const sc = M.scoring;
  let verdict;
  if (risk >= sc.phishing_at && h < sc.corroboration) {
    findings.push({ rule: "model_only", severity: "info",
      detail: "tree flags the URL structure but no rule corroborates it; analyst review" });
    verdict = "SUSPICIOUS";
  } else if (risk >= sc.phishing_at) verdict = "PHISHING";
  else if (risk >= sc.suspicious_at) verdict = "SUSPICIOUS";
  else verdict = "CLEAN";

  findings.sort((a, b) => weight(b) - weight(a));
  return { url, verdict, risk, tree_probability: pTree, heuristic_score: h, trusted_domain: trusted,
    findings, decision_path: path, features: feats };
}
